local _, ns = ...
local E = ns.DB.entries
E["npc:captain-greenskin"] = {t="npc",n="Captain Greenskin",z="deadmines",s="Captain Greenskin is an elite goblin pirate overseeing the construction and crew of Edwin VanCleef's massive ironclad juggernaut. Hidden deep in the subterranean cove of the Deadmines, he commands the pirate forces hired by the Defias Brotherhood. His goal is to bring the warship to readiness to sail against Stormwind.",h="Captain Greenskin is an elite goblin pirate overseeing the construction and crew of Edwin VanCleef's massive...",sec={{t="Master of the Juggernaut",b="Pacing the main deck of the gigantic juggernaut under construction in the Deadmines cove, Captain Greenskin represents the naval backbone of the Defias conspiracy. A seasoned goblin mariner who previously operated out of Booty Bay, Greenskin was brought into Edwin VanCleef's inner circle to turn an underground cavern into a drydock for an engine of war.",sp=0},{t="A Pirate's Crew",b="Greenskin does not command an ordinary crew of stonemasons or bandits. Under his direct watch serve seasoned cutthroats, including his fearsome tauren first mate Mr. Smite and the murloc ship's cook, Cookie. Together, they hold the ship's gangplanks and upper deck, standing between intruders and VanCleef's private cabin atop the bridge.",sp=0}},faq={{q="Who is Captain Greenskin?",a="Captain Greenskin is a goblin pirate captain hired by Edwin VanCleef to supervise the completion and operation of the Defias Brotherhood's secret war juggernaut in the Deadmines.",al={"greenskin lore","who is greenskin","captain greenskin"}},{q="Where did Greenskin come from before joining the Defias?",a="Greenskin originally hails from Booty Bay in the southern reaches of Stranglethorn Vale, where he formerly commanded a fleet of pirate vessels before entering VanCleef's pay.",al={"greenskin origin","where is greenskin from","greenskin booty bay"}},{q="Who serves under Captain Greenskin?",a="His command includes his first mate, the tauren Mr. Smite, as well as Cookie the murloc cook and a contingent of Defias pirates patrolling the ironclad's deck.",al={"greenskin crew","first mate","greenskin minions"}},{q="What is Greenskin's purpose in the Deadmines?",a="He is tasked with making the massive ironclad warship seaworthy and prepared to sail out of the subterranean grotto into the Great Sea to strike at the kingdom of Stormwind.",al={"what does greenskin do","why is greenskin here"}},{q="Where can Captain Greenskin be found?",a="He paces the main deck of the large juggernaut anchored in the final cavern of the Deadmines, guarding the approach to Edwin VanCleef.",al={"greenskin location","where is captain greenskin"}},{q="Is Captain Greenskin part of the Defias Brotherhood or a mercenary?",a="He is a mercenary pirate captain in the direct employ of Edwin VanCleef, commanding the naval forces aligned with the Defias Brotherhood's plot.",al={"is greenskin defias","greenskin faction"}}},ang={["faction:Alliance"]="For Alliance forces, Captain Greenskin represents the maritime threat of the Defias rebellion; if his juggernaut breaches the coast, the undefended shores of Westfall and Stormwind are at direct risk.",["class:Rogue"]="Greenskin stands at the apex of Defias piracy, heavily guarded by corsairs and brutes right on the warship's deck."},kw={"booty bay","captain greenskin","deadmines","goblin pirate","greenskin","juggernaut","smite","vancleef"},rel={"npc:edwin-vancleef","npc:mr-smite","npc:cookie","zone:deadmines","subzone:booty-bay","topic:pirate","topic:goblin","topic:alliance"},src={"Captain Greenskin"}}
E["npc:cookie"] = {t="npc",n="Cookie",z="deadmines",s="Cookie is an elite murloc serving as the ship's cook aboard the juggernaut hidden deep within the Deadmines. An unusual recruit among the Defias Brotherhood, he tends the crew's cauldrons beneath the watchful eye of Captain Greenskin and Edwin VanCleef. He is the only entirely optional boss encountered within the underground dry dock.",h="Cookie is an elite murloc serving as the ship's cook aboard the juggernaut hidden deep within the Deadmines.",sec={{t="The Brotherhood's Chef",b="Beneath the decks of the towering juggernaut in the Ironclad Cove, cooking duty falls neither to a human outrider nor a goblin engineer, but to a solitary murloc known simply as Cookie. How he secured the position remains a private secret kept by Edwin VanCleef himself. Whatever doubts the rest of the crew might harbor about a murloc presiding over their rations, pirates are rarely in a position to be picky, and in the underworld of Moonbrook, a meal is a meal.",sp=0},{t="A Bitter Brew",b="Cookie patrols the waterways and shores around the pirate flagship, wielding his cooking utensils alongside acidic brews. Despite being isolated from typical murloc tribes, he defends his cauldron with savage ferocity, flinging caustic concoctions at any intruders who wander into the docks. Because his station sits away from the main gangplanks, many who storm the cove bypass his kitchen entirely, making him the only optional overseer aboard the Defias juggernaut.",sp=0}},faq={{q="Why is a murloc working as a cook for the Defias?",a="Edwin VanCleef is the only one who knows why Cookie was recruited and granted the galley duties. The Defias outlaws and goblin shipwrights simply accept the arrangement because pirate crews take food where they can get it, regardless of the chef's species.",al={"why murloc cook","why is cookie on the ship","cookie defias lore"}},{q="Where can Cookie be found in the Deadmines?",a="Cookie is located in the Ironclad Cove at the very end of the Deadmines. He patrols the shallow water and docks near the stern of the giant wooden juggernaut, just past the ramp where Mr. Smite stands guard.",al={"where is cookie","cookie location deadmines","finding cookie"}},{q="Is Cookie required to finish the Deadmines?",a="No, Cookie is the only optional boss in the dungeon. Infiltrators can board the vessel directly to confront Captain Greenskin and Edwin VanCleef without ever disturbing the cook's patrol along the shore.",al={"is cookie optional","do you have to kill cookie","cookie skip"}},{q="Does Cookie belong to a specific murloc tribe?",a="Cookie is not associated with any of the known local murloc tribes, such as those along the Westfall coast. He lives and works entirely among the outlaws and scoundrels of the Defias Brotherhood.",al={"what tribe is cookie","cookie murloc tribe"}},{q="What weapons or attacks does Cookie use?",a="Cookie wields cooking implements in melee combat and can hurl caustic splashes of acid at attackers, burning them with dangerous culinary mixtures.",al={"cookie abilities","how does cookie fight","cookie attacks"}},{q="Who does Cookie report to on the juggernaut?",a="Cookie directly serves the naval arm of the Defias Brotherhood under the command of Captain Greenskin, answering ultimately to Edwin VanCleef himself.",al={"cookie boss","who leads cookie","cookie greenskin vancleef"}}},ang={["profession:Cooking"]="Finding a murloc appointed as chief cook aboard an outlaw juggernaut is a testament to the desperate, unrefined standards of pirate cuisine.",["class:Rogue"]="VanCleef's rogue network relies on strange, unconventional assets, and Cookie proves that even the Brotherhood's supply lines feature odd surprises.",["faction:Alliance"]="Stormwind's scouts are often surprised to find murlocs actively working within the Defias leadership rather than merely infesting Westfall's outer shores."},kw={"captain greenskin","cook","cookie","deadmines","defias","edwin vancleef","ironclad cove","juggernaut","murloc"},rel={"npc:captain-greenskin","npc:edwin-vancleef","npc:mr-smite","zone:deadmines","topic:murloc","topic:pirate"},src={"Cookie"}}
E["npc:edwin-vancleef"] = {t="npc",n="Edwin VanCleef",z="deadmines",s="Edwin VanCleef was the brilliant Guildmaster of the Stonemasons who rebuilt Stormwind City after the Second War. After being cheated of payment by the House of Nobles, he led a violent workers' revolt and formed the outlaw Defias Brotherhood. Operating from deep within the Deadmines of Westfall, he seeks vengeance against the kingdom he helped restore.",h="Edwin VanCleef was the brilliant Guildmaster of the Stonemasons who rebuilt Stormwind City after the Second...",sec={{t="Architect of the Kingdom",b="Following the devastation of the First War, Edwin VanCleef was chosen to lead the Stonemasons Guild in the monumental task of rebuilding Stormwind City. A peerless craftsman and an idealist, VanCleef directed the construction of the capital's grand ramparts and towering cathedrals, and even oversaw the erection of Nethergarde Keep to watch over the Dark Portal. Alongside his mastery of architecture, VanCleef was a remarkably deadly operative; he was trained in stealth, subterfuge, and bladecraft by his childhood friend, Mathias Shaw.",sp=0},{t="The Riot and the Brotherhood",b="When the years of labor concluded, the House of Nobles ran up colossal debts through military campaigns and refused to provide the Stonemasons their promised compensation. Enraged, VanCleef demanded restitution, only for the nobles to officially dissolve the guild. The artisans revolted, triggering chaotic street riots in Stormwind during which King Varian Wrynn's wife, Queen Tiffin, was slain. Driven out of the capital by the crown's retribution, VanCleef gathered his exiled workers and allied outcasts in Westfall, uniting them beneath the banner of the Defias Brotherhood.",sp=0},{t="Retribution from the Shadows",b="Taking advantage of the crown's neglect of the countryside, the Defias drove off Westfall's farmers and claimed its rich gold deposits. Within the depths of Moonbrook's Deadmines, VanCleef oversaw the construction of a massive juggernaut warship, preparing an armed assault against Stormwind itself. While the House of Nobles dismissed the thieves as disorganized brigands, VanCleef forged alliances with river crooks, gnolls, and the Bloodsail Buccaneers, turning an embittered labor union into an army poised to crush the monarchy.",sp=1}},faq={{q="Who is Edwin VanCleef?",a="He is the mastermind behind the Defias Brotherhood and the former Guildmaster of the Stonemasons. He is the master architect who rebuilt Stormwind City after the Horde destroyed it during the First War.",al={"who is vancleef","edwin vancleef lore","vancleef identity"}},{q="Why did the Stonemasons revolt against Stormwind?",a="After the rebuilding of Stormwind City, the House of Nobles refused to pay the Stonemasons Guild their agreed wages due to excessive kingdom debt. When VanCleef and the workers protested, the nobles disbanded the guild, igniting violent riots in the streets.",al={"why did defias rebel","why did stonemasons riot","reason for defias riot"}},{q="Where is Edwin VanCleef hiding?",a="He commands the Defias Brotherhood from the innermost sanctum of the Deadmines in Westfall, stationed aboard a massive warship hidden in an underground iron cove beneath Moonbrook.",al={"where is vancleef","vancleef location","deadmines boss location"},sp=1},{q="What is his connection to Mathias Shaw?",a="Mathias Shaw was a childhood friend of Edwin. Shaw personally trained VanCleef in the arts of stealth, thievery, and combat, originally hoping VanCleef would join him in the royal intelligence agency SI:7.",al={"vancleef and shaw","is vancleef related to shaw","mathias shaw friend"}},{q="What happened to Queen Tiffin during the riot?",a="During the chaotic street riots stirred by the unpaid Stonemasons, a hurled stone struck and killed King Varian's young wife, Queen Tiffin Wrynn. Her death drove King Varian into a furious crackdown, forcing VanCleef and his men to flee the city.",al={"how did tiffin die","who killed tiffin wrynn","queen tiffin death"}},{q="What is he building in the Deadmines?",a="VanCleef is constructing a massive iron-plated juggernaut warship inside the flooded subterranean docks of the Deadmines, using stolen Westfall gold and foundry machinery to prepare an armed naval strike against Stormwind.",al={"deadmines ship","what is inside deadmines","vancleef warship"},sp=1}},ang={["race:Human"]="For humans of Stormwind, VanCleef embodies the tragedy of the kingdom's postwar recovery: a loyal hero whose denied livelihood turned him into the realm's deadliest insurgent.",["class:Rogue"]="VanCleef was trained by SI:7 leader Mathias Shaw himself, making him one of the most capable rogues in Azeroth, blending formal guild leadership with elite assassination techniques.",["faction:Alliance"]="Alliance commanders consider VanCleef the premier internal security threat to southern human lands, paralyzing Westfall and the borders of Elwynn Forest."},kw={"brotherhood","deadmines","defias","moonbrook","stonemasons","stormwind","vancleef","westfall"},rel={"topic:defias-brotherhood","topic:stonemasons-guild","zone:deadmines","zone:westfall","npc:mathias-shaw","npc:baros-alexston","npc:gryan-stoutmantle","quest:373"},src={"Edwin VanCleef"}}
E["npc:gilnid"] = {t="npc",n="Gilnid",z="deadmines",s="Gilnid, known as the Smelter, is the goblin master engineer running the forges in the depths of the Deadmines. He oversees the smelting of raw ore into refined metal and munitions for Edwin VanCleef's hidden ironclad juggernaut. Without his fiery operations, the Defias Brotherhood would lack the heavy cannons needed to assault Stormwind.",h="Gilnid, known as the Smelter, is the goblin master engineer running the forges in the depths of the Deadmines.",sec={{t="Master of the Foundry",b="Deep within the Deadmines, the Defias Brotherhood relies on industrial expertise to forge weapons of war. Gilnid serves as VanCleef's head smelter, commanding a small army of goblin laborers, tinkers, and smiths in the central foundry. Towering over most of his kin, he drives his crew relentlessly through smoke and slag, barking orders and refusing breaks to ensure raw iron ore is processed into heavy plating and lethal ordnance.",sp=0},{t="Arming the Juggernaut",b="The smelting works are critical to the Brotherhood's grand ambition. Gilnid is directly responsible for forging the heavy cannons and ammunition intended for the colossal ironclad warship docked in the subterranean cove beyond his workshop. Until his foundry churns out every gun, barrel, and ball, the Defias vessel remains unready for its planned strike against Stormwind.",sp=1}},faq={{q="Who is Gilnid?",a="Gilnid is a goblin engineer and the head smelter for Edwin VanCleef in the Deadmines. He oversees the Brotherhood's forges and leads the industrial effort to cast cannons and ammunition for their war machine.",al={"gilnid deadmines","who is gilnid","the smelter"}},{q="Why is Gilnid in the Deadmines?",a="The Defias Brotherhood hired mercenary goblin engineers to build and supply their hidden warship. Gilnid was placed in charge of the smelting works, transforming mined iron ore into refined parts, armor, and artillery.",al={"why is a goblin in deadmines","gilnid defias lore","what is gilnid doing"}},{q="What is Gilnid working on?",a="Gilnid is responsible for manufacturing the massive cannons, ship parts, and shot needed to arm the juggernaut hidden in the docks deeper inside the mines.",al={"gilnid cannon","what is gilnid building","deadmines forge purpose"}},{q="Why must Gilnid be defeated?",a="Gilnid controls the industrial foundry blocking the path to the cove. The heavy blast doors leading deeper toward the Defias ship remain sealed until the smelting room is secured.",al={"why kill gilnid","door past gilnid"}},{q="Does Gilnid work directly for Edwin VanCleef?",a="Yes. He is not a member of the original Stonemasons, but rather a contracted goblin specialist serving directly under VanCleef to handle heavy metallurgy and weapons production.",al={"vancleef and gilnid","is gilnid defias leader"}},{q="Why are there so many goblins around him?",a="Gilnid leads a specialized goblin engineering crew in the foundry. They operate the blast furnaces, pour molten iron, and assemble ordnance under his strict, unrelenting supervision.",al={"gilnid goblins","deadmines forge crew"}}},ang={["profession:Mining"]="The massive blast furnaces and smelting pots in Gilnid's workshop demonstrate how the Defias Brotherhood turns the raw mineral wealth of Westfall into refined iron and armaments.",["profession:Engineering"]="Gilnid's foundry is a prime example of goblin heavy industry, churning out standardized naval cannons, ammunition, and structural plating under extreme conditions.",["faction:Alliance"]="Stopping Gilnid shuts down the Defias weapons assembly line, preventing VanCleef's warship from being fully armed before it can threaten Stormwind Harbor."},kw={"cannons","deadmines","defias","forge","foundry","gilnid","goblin","juggernaut","smelter","vancleef"},rel={"npc:edwin-vancleef","zone:deadmines","topic:defias-brotherhood","topic:goblin","quest:65"},src={"Gilnid"}}
E["npc:miner-johnson"] = {t="npc",n="Miner Johnson",z="deadmines",s="Miner Johnson is an elusive, seasoned miner affiliated with the Defias Brotherhood deep inside the Deadmines. Tucked away in a side alcove alongside ordinary laborers, this dangerous prospector oversees excavation efforts ahead of the heavy machinery found deeper underground. Because he wanders the subterranean tunnels erratically, adventurers only occasionally cross his path.",h="Miner Johnson is an elusive, seasoned miner affiliated with the Defias Brotherhood deep inside the Deadmines.",sec={{t="A Rare Face in the Deep",b="While hundreds of laborers pick at the subterranean veins of the Deadmines to supply Edwin VanCleef's hidden fortress, Miner Johnson stands out as an unusually formidable figure among them. Lurking in a shadowed alcove to the left before the lumbering shredders of the Mast Room, he is far tougher and more aggressive than the regular workforce. His unpredictable presence makes him a legendary target for explorers traversing the Defias tunnels.",sp=0},{t="Fueling the Defias War Machine",b="The Defias Brotherhood's clandestine operation beneath Moonbrook requires vast amounts of raw ore to forge weapons, reinforce shafts, and assemble mechanical contraptions. Miners like Johnson provide the muscle behind the metal, hacking away at the rich mineral seams beneath Westfall. Anyone stumbling into Johnson's workspace will quickly discover that he defends his dig site with lethal fervor.",sp=0}},faq={{q="Who is Miner Johnson?",a="Miner Johnson is a rare elite human miner allied with the Defias Brotherhood. He works deep within the Deadmines, situated in a side alcove with other laborers just before the goblin shredder.",al={"miner johnson lore","who is miner johnson","deadmines miner johnson"}},{q="Where exactly is Miner Johnson located?",a="He can be found in the upper shafts of the Deadmines before reaching the room housing Sneed and his shredder. Look for a small excavation alcove off to the left where a pocket of miners are actively chipping away at the rock.",al={"miner johnson location","where is miner johnson","how to find miner johnson"}},{q="Why isn't Miner Johnson always there?",a="Miner Johnson is a rare spawn, meaning he only appears occasionally when an expedition enters the Deadmines. Most groups running through the mine shafts will find an ordinary miner in his place instead.",al={"miner johnson not spawning","is miner johnson rare","miner johnson spawn rate"}},{q="Is Miner Johnson part of any quest?",a="Miner Johnson is not associated with any formal quest bounty. He is simply an opportunistic encounter for dungeon delve parties lucky enough to find him working the seam.",al={"miner johnson quest","does miner johnson have a quest"}},{q="What is Miner Johnson's role in the Deadmines?",a="He is an experienced foreman or master digger helping the Defias Brotherhood extract precious metal, stone, and resources necessary to construct their massive underground base and hidden juggernaut.",al={"what does miner johnson do","miner johnson role"}},{q="Is Miner Johnson dangerous compared to other miners?",a="Yes. While the standard diggers throughout the Deadmines are relatively fragile, Miner Johnson is an elite combatant with significantly more vitality and striking power, requiring a coordinated group to bring down safely.",al={"how hard is miner johnson","is miner johnson elite"}}},ang={["profession:Mining"]="For prospectors, Johnson represents the rugged, lawless side of subterranean labor, guarding rich mineral deposits deep beneath Westfall with blood and pickaxe.",["faction:Alliance"]="Striking down Johnson disrupts the steady stream of smeltable ore flowing into the Defias war machine hidden below Moonbrook."},kw={"alcove","deadmines","defias","elite","miner johnson","moonbrook","rare","shredder","westfall"},rel={"zone:deadmines","subzone:deadmines"},src={"Miner Johnson"}}
E["npc:mr-smite"] = {t="npc",n="Mr. Smite",z="deadmines",s="Mr. Smite is the imposing tauren first mate serving aboard the Defias Brotherhood's flagship deep inside the Deadmines. An expert weaponmaster under Captain Greenskin, he commands the dockside approach to the hidden juggernaut with ruthless discipline. Intruders who face him must contend with his shifting arsenal and devastating physical strength.",h="Mr.",sec={{t="First Mate of the Cove",b="Guarding the docks of Ironclad Cove, Mr. Smite serves as first mate to the goblin Captain Greenskin. While the Defias Brotherhood is predominantly composed of disenfranchised humans and allied goblin tinkerers, Smite stands as a striking anomaly: a massive, battle-hardened tauren far from the plains of Kalimdor. Tasked with maintaining strict order among a rowdy pirate crew, he ensures that the labor fitting out Edwin VanCleef's secret dreadnaught proceeds without disruption.",sp=0},{t="A Deadly Weaponmaster",b="Smite is not merely a brute enforcer; he is a theatrical and versatile weaponmaster. He delights in toying with would-be heroes, deliberately prolonging combat to offer opponents a false sense of hope. When pressed, he unleashes a staggering, earth-shattering stomp that leaves foes stunned while he rummages through his nearby weapon chest. Beginning combat with a nimble dueling blade, he will escalate to twin cleaving reavers, and finally resort to his colossal two-handed warhammer when thoroughly provoked.",sp=0}},faq={{q="Why is a tauren working with human bandits in Westfall?",a="While the vast majority of tauren dwell in Kalimdor alongside their Horde allies, mercenary outcasts and wanderers occasionally find their way east. Smite serves as a pirate officer rather than an ideological follower of the Defias Brotherhood, hired alongside Captain Greenskin's crew to supervise the cove and ready the dreadnaught for sea.",al={"why tauren in deadmines","mr smite lore","tauren pirate"}},{q="Who is Mr. Smite's superior?",a="Smite answers directly to Captain Greenskin, the goblin master of the pirate vessel anchored in Ironclad Cove. Above them both in the overall conspiracy stands Edwin VanCleef, the grand leader of the Defias Brotherhood.",al={"who is smite's boss","who does mr smite work for"}},{q="What weapons does Mr. Smite use during the fight?",a="Smite begins battle with a Thief's Blade. As the fight turns against him, he retreats to his chest to equip a pair of Smite's Reavers, and finally draws out Smite's Mighty Hammer when pushed to his limits.",al={"smite weapons","what does smite pull out of the chest"}},{q="Where can Mr. Smite be found?",a="Mr. Smite stands watch on the wooden piers of Ironclad Cove, the final cavern within the Deadmines, guarding the gangplank leading up to the giant Defias dreadnaught.",al={"mr smite location","where is smite"}},{q="Does Mr. Smite fight alone?",a="Smite keeps two stealthy Defias rogues hidden at his side, ready to ambush any trespassers who advance down the pier toward the ship.",al={"smite adds","smite bodyguards"}},{q="What makes Mr. Smite so dangerous in close quarters?",a="His signature tauren War Stomp sends shockwaves through the wooden dock, stunning entire parties of adventurers long enough for him to rearm himself from his footlocker and resume the assault with heavier weaponry.",al={"smite stun","smite war stomp"}}},ang={["race:Tauren"]="Seeing a fellow tauren serving as a cutthroat first mate among seafaring outlaws in the Eastern Kingdoms is a jarring sight for any traveler from Mulgore.",["class:Warrior"]="Smite demonstrates remarkable martial discipline, seamlessly transitioning between swift single-handed strikes, dual-wielded axes, and punishing two-handed hammer blows.",["faction:Alliance"]="Smite serves as the primary barrier preventing Alliance agents from storming the gangplank to reach Captain Greenskin and Edwin VanCleef."},kw={"captain greenskin","deadmines","first mate","ironclad cove","mr smite","mr. smite","smite's mighty hammer","smite's reaver","tauren pirate","thief's blade"},rel={"subzone:ironclad-cove","npc:captain-greenskin","zone:deadmines","subzone:deadmines","topic:tauren"},src={"Mr. Smite"}}
E["npc:rhahk-zor"] = {t="npc",n="Rhahk'Zor",z="deadmines",s="Rhahk'Zor is a hulking ogre serving as the head foreman within the Deadmines. Overseeing Edwin VanCleef's subterranean construction efforts, he keeps the Defias laborers and miners in line through sheer brute force and heavy-handed discipline.",h="Rhahk'Zor is a hulking ogre serving as the head foreman within the Deadmines.",sec={{t="The Foreman of the Deep",b="Deep beneath the rolling hills of Westfall, the Defias Brotherhood has transformed the abandoned gold mines of Moonbrook into an underground fortress. Coordinating this sprawling construction requires harsh discipline, a role filled by the ogre Rhahk'Zor. Appointed as head foreman, he oversees the excavation crews and laborers, driving them forward to carve out tunnels and assemble VanCleef's secret projects.",sp=0},{t="Brute Motivation",b="Rhahk'Zor maintains order through relentless muscle rather than careful engineering. Armed with an immense stone-headed hammer, his idea of workplace supervision is direct and unforgiving. Defias diggers and goblin engineers alike step lively around him, knowing that falling behind schedule or showing defiance invites a crushing blow from the towering taskmaster.",sp=0}},faq={{q="Who is Rhahk'Zor?",a="Rhahk'Zor is an ogre who acts as the primary foreman and enforcer for the Defias Brotherhood inside the Deadmines. He stands watch over the initial excavation tunnels, ensuring the workforce keeps digging without stepping out of line.",al={"rhahkzor","who is the ogre boss in deadmines","deadmines first boss"}},{q="Why is an ogre working for the Defias Brotherhood?",a="Edwin VanCleef's rebellion relies on whatever muscle and mercenary talent they can acquire. An ogre provides unmatched physical intimidation, making Rhahk'Zor an ideal taskmaster to drive the grueling labor of excavating the mines.",al={"why is there an ogre in deadmines","rhahkzor defias"}},{q="What is Rhahk'Zor's job in the mines?",a="He serves as the head construction foreman. Rhahk'Zor supervises the miners, goblins, and Defias builders as they hollow out the caverns, maintain equipment, and build fortifications for the Brotherhood.",al={"what does rhahkzor do","rhahkzor role"}},{q="Where in the Deadmines is Rhahk'Zor located?",a="Rhahk'Zor guards the early quarry chambers of the Deadmines, standing past the initial miner tunnels and right before the heavy iron threshold known as Rhahk'Zor's Door.",al={"rhahkzor location","where is rhahkzor"}},{q="Does Rhahk'Zor have any connection to the ogres from the First War?",a="Ogres once inhabited the Deadmines during the First War before being wiped out by Blackhand's Horde. Whether Rhahk'Zor is a lingering remnant of those earlier clans or simply a brute hired by VanCleef remains unconfirmed.",al={"first war ogres deadmines","ogre lore deadmines"}},{q="What happens when Rhahk'Zor is defeated?",a="Defeating Rhahk'Zor breaks the Defias hold on the outer quarry, clearing the way through the reinforced blast door he guards and allowing trespassers deeper into the clandestine shipyards and workshops.",al={"rhahkzor door","after rhahkzor"}}},ang={["faction:Alliance"]="For Alliance adventurers pushing into Moonbrook, Rhahk'Zor is the first grim proof that the Defias Brotherhood has organized far beyond petty highway banditry into a heavily fortified army.",["class:Warrior"]="Facing Rhahk'Zor is a test of raw frontline endurance, pitted against a massive ogre swinging a sledgehammer that shatters stone and bone alike.",["profession:Mining"]="Rhahk'Zor drives his miners with crude brutality rather than respect for the veins of gold, churning Westfall's storied old mines into a rushed industrial war machine."},kw={"deadmines","defias","foreman","hammer","ogre","rhahk'zor","rhahkzor","vancleef"},rel={"zone:deadmines","topic:defias-brotherhood","npc:edwin-vancleef","subzone:deadmines","quest:65","topic:first-war"},src={"Rhahk'Zor"}}
E["npc:scout-riell"] = {t="npc",n="Scout Riell",z="deadmines",s="Scout Riell is a vigilant lookout stationed atop the watchtower at Sentinel Hill in Westfall. Serving the local People's Militia, she watches the surrounding plains for Defias activity and enlists adventurers to hunt down the masked outlaws.",h="Scout Riell is a vigilant lookout stationed atop the watchtower at Sentinel Hill in Westfall.",sec={{t="Eyes Over Westfall",b="Perched high above Sentinel Hill, Scout Riell keeps watch over a region besieged by banditry and harvest golems. With Stormwind's royal army absent and the crown refusing aid, local defense falls entirely to the People's Militia. From her vantage point atop the stone tower, Riell tracks the brazen movements of the Defias Brotherhood and gathers proof of their crimes, calling on passing travelers to strip the bandits of their iconic red silk bandanas.",sp=0}},faq={{q="Where can I find Scout Riell?",a="Scout Riell is located at Sentinel Hill in Westfall. Climb the stairs all the way to the open-air roof of the stone watchtower, where she keeps watch over the plains.",al={"riell location","where is scout riell","find riell"}},{q="What does Scout Riell ask adventurers to do?",a="Riell tasks adventurers with collecting red silk bandanas directly from the Defias cutpurses, highwaymen, and smugglers roaming Westfall and hiding out in the Deadmines, proving that local outlaws have been slain.",al={"riell quest","what quest does riell give","red silk bandanas quest"}},{q="Why does Riell collect red silk bandanas?",a="The red silk bandana is the universal badge of the Defias Brotherhood. Collecting them serves as solid proof that the bandits terrorizing Westfall's homesteads are being reduced, and it denies the outlaws their unifying symbol.",al={"why bandanas","why red silk bandanas","defias masks"}},{q="Who does Scout Riell work for?",a="Riell serves the People's Militia, the volunteer defense force formed by Gryan Stoutmantle to protect Westfall when the House of Nobles in Stormwind turned a blind eye to the province's plight.",al={"riell faction","is riell stormwind army","who does riell serve"}}},ang={["faction:Alliance"]="For Alliance champions, Scout Riell represents the grim reality of Westfall: an abandoned populace forced to hire mercenary aid to fight the rising threat of the Defias Brotherhood.",["profession:Tailoring"]="Tailors will note that the Defias' signature red masks are fashioned from genuine silk, a remarkably expensive fabric for common rural highwaymen."},kw={"defias brotherhood","people's militia","red silk bandanas","riell","scout riell","sentinel hill","tower","westfall"},rel={"subzone:sentinel-hill","zone:westfall","quest:214","quest:12","zone:deadmines"},src={"Scout Riell"}}
E["npc:shoni-the-shilent"] = {t="npc",n="Shoni the Shilent",z="deadmines",s="Shoni the Shilent is an industrious gnome engineer stationed in Stormwind City's bustling Dwarven District. As commander of the Gnomeregan underground assault crew, she directs Alliance adventurers into the Deadmines to salvage the power supply of a goblin shredder, fuel for the machines she hopes will break a path back into Gnomeregan.",h="Shoni the Shilent is an industrious gnome engineer stationed in Stormwind City's bustling Dwarven District.",sec={{t="Commander of the Deep",b="Operating out of the smoky workshops of the Dwarven District, Shoni represents gnomish strategic ingenuity far from the lost halls of Gnomeregan. Though quiet in demeanor—earning her the moniker 'the Shilent'—her engineering plans are ambitious. With Gnomeregan in the hands of the troggs, Shoni is organizing an underground assault to retake it, and she sends operatives into the subterranean tunnels beneath Westfall for the parts her crew needs.",sp=0},{t="Subterranean Reclamation",b="Shoni's plan rests on the gnomes' own gyrodrillmatic excavationators, heavy drilling machines meant to break through the rocky underground borders of Gnomeregan and open the way for a gnomish assault. They lack the power to do it, so she wants the intact power supply, the Gnoam Sprecklesprocket, from a working goblin shredder deep in the Deadmines. Later, she also sends adventurers into Gnomeregan itself to tear apart its robots for spare parts to repair her fleet.",sp=0}},faq={{q="Who is Shoni the Shilent?",a="Shoni the Shilent is a gnome quest giver located in Stormwind's Dwarven District. She acts as the commander of the Gnomeregan underground assault crew and coordinates subterranean reclamation missions.",al={"who is shoni","shoni lore","shoni the shilent npc"}},{q="Where can I find Shoni?",a="She is stationed among the anvils and workshops of the Dwarven District in Stormwind City, near the blacksmithing and engineering areas.",al={"where is shoni","shoni location","find shoni"}},{q="Why is Shoni interested in the Deadmines?",a="A functional goblin shredder works deep in the Deadmines. Shoni enlists adventurers to bring back its intact power supply, the Gnoam Sprecklesprocket, so her gyrodrillmatic excavationators can break through the underground borders of Gnomeregan.",al={"shoni deadmines","why send to deadmines","gyrodrillmatic quest"}},{q="Why is she called 'the Shilent'?",a="Her moniker is a playful gnomish epithet highlighting her focused, understated nature, which stands in stark contrast to the typically noisy, eccentric chatter found among gnomish tinkers.",al={"shoni nickname","why shilent","silent gnome"}}},ang={["race:Gnome"]="For gnomish heroes, assisting Shoni brings their people one step closer to breaking back into Gnomeregan and reclaiming their fallen home.",["profession:Engineering"]="Engineers can appreciate the sheer mechanical complexity of the gyrodrillmatic excavationators Shoni hopes to power with a shredder's salvaged heart from beneath Moonbrook."},kw={"deadmines","dwarven district","excavationators","gnome","gyrodrillmatic","shilent","shoni","stormwind"},rel={"subzone:dwarven-district","zone:stormwind","zone:deadmines","quest:2040","quest:2928","quest:2041","topic:gnome","zone:gnomeregan"},src={"Shoni the Shilent"}}
E["npc:sneed"] = {t="npc",n="Sneed",z="deadmines",s="Sneed is the Defias Brotherhood's goblin lumbermaster stationed deep within the Deadmines. Operating from the lumber chamber known as the Mast Room, he pilots a heavy shredder of his own design to process timber for Edwin VanCleef's secret juggernaut.",h="Sneed is the Defias Brotherhood's goblin lumbermaster stationed deep within the Deadmines.",sec={{t="The Defias Lumbermaster",b="While the Defias Brotherhood draws its core membership from disenfranchised human stonemasons and common laborers, building an ironclad warship requires specialist trades. Edwin VanCleef recruited Sneed specifically for his engineering know-how and ruthless goblin efficiency. Stationed in the Mast Room along the subterranean rail network, Sneed oversees the rapid felling, cutting, and shaping of timber needed to frame VanCleef's colossal dreadnaught.",sp=0},{t="Industrial Brutality",b="Sneed's primary concern is cutting costs and meeting deadlined quotas, consequences be damned. To speed up the process, he commands the floor from inside a customized shredder equipped with oversized buzz saws. The deadly machine turns raw trunks into shipbuilding timber in seconds. If cornered by intruders, Sneed relies on the armor of his machine to grind them down, but he is more than willing to scramble out of the wreckage and fight with his bare hands if his contraption fails.",sp=0}},faq={{q="Who is Sneed?",a="Sneed is a goblin engineer and lumbermaster employed by Edwin VanCleef. He is tasked with overseeing the processing of lumber inside the Deadmines to build the Defias juggernaut.",al={"who is sneed","sneed lore","what is sneed"}},{q="Where can Sneed be found?",a="Sneed is located in the Mast Room, an industrial lumber mill chamber situated along the mining tracks inside the Deadmines beneath Moonbrook.",al={"sneed location","where is sneed","sneed room"}},{q="Why is a goblin working for the Defias Brotherhood?",a="Edwin VanCleef needed specialized industrial knowledge and fast results to construct his secret warship. He hired mercenary goblins like Sneed who care little about politics or ethics as long as the coin is good.",al={"why is sneed with defias","goblin in deadmines","why defias hire goblins"}},{q="What is Sneed piloting in battle?",a="Sneed pilots Sneed's Shredder, a heavy, saw-wielding bipedal mechanical harvester that he built himself to harvest and slice timber at terrifying speeds.",al={"sneed robot","sneed mech","sneed's shredder"}},{q="What happens when his shredder is destroyed?",a="Destroying the shredder does not finish the fight. Sneed ejects from the smoking remains of the machine and continues fighting intruders directly on foot.",al={"sneed phase 2","sneed out of shredder","does sneed die with shredder"}},{q="What is Sneed building timber for?",a="The timber cut in Sneed's chamber is transported downstream to the Ironclad Cove, where the Brotherhood is assembling a massive warship intended to strike back against Stormwind.",al={"why sneed cutting wood","mast room purpose","deadmines wood"}}},ang={["profession:Engineering"]="Sneed's customized shredder showcases classic goblin craftsmanship: devastatingly efficient, heavily armed, and pushed far past standard safety tolerances to maximize production speed.",["race:Gnome"]="Gnomish visitors to the Mast Room will find Sneed's machine a typical example of goblin ingenuity—loud, hazardous, and built without regard for operator comfort or structural longevity.",["faction:Alliance"]="Taking down Sneed cripples the supply of timber heading toward the Ironclad Cove, striking a critical blow against the Defias Brotherhood's shipbuilding efforts."},kw={"deadmines","edwin vancleef","goblin","juggernaut","lumbermaster","mast room","shredder","sneed","sneed's shredder"},rel={"npc:sneed-s-shredder","subzone:mast-room","zone:deadmines","npc:edwin-vancleef","topic:goblin"},src={"Sneed"}}
E["npc:sneed-s-shredder"] = {t="npc",n="Sneed's Shredder",z="deadmines",s="Sneed's Shredder is an imposing mechanised lumber harvester stationed deep within the Deadmines. Piloted by the goblin taskmaster Sneed, this deadly machine acts as both heavy industrial machinery for Edwin VanCleef's shipwrights and a terrifying perimeter defender.",h="Sneed's Shredder is an imposing mechanised lumber harvester stationed deep within the Deadmines.",sec={{t="Industrial Terror",b="Within the goblin-dominated foundry of the Deadmines, mechanical shredders serve a dual purpose: processing vast amounts of timber and lumber required for Edwin VanCleef's hidden juggernaut, and serving as armored shock engines against intruders. Sneed, the overseer of the lumber works, operates this modified mechanical beast directly, turning an oversized buzzsaw into an instrument of defense.",sp=0},{t="A Deadly Cockpit",b="Defeating the machine does not end the threat. Sneed perches inside an open cockpit above the spinning blades, relying on heavy iron plating and terrifying clatter to scatter his foes. Even when the machinery breaks down and the shredder collapses in a shower of sparks, Sneed leaps from the smoking wreckage to fight to the bitter end.",sp=0}},faq={{q="What is Sneed's Shredder used for in the Deadmines?",a="The Defias Brotherhood relies heavily on goblin machinery to carve through subterranean stone and process massive quantities of timber needed to construct their secret juggernaut. Sneed uses this shredder to mill wood and brutally enforce order over the underground works.",al={"why is there a shredder in deadmines","shredder purpose deadmines"}},{q="What happens when the shredder is destroyed?",a="When the shredder suffers critical mechanical failure, Sneed himself survives the wreckage. The goblin pilot emerges directly from the ruined vehicle, brandishing his own weapons and attacking intruders with fierce tenacity.",al={"does sneed die with the shredder","sneed shredder phase 2"}},{q="Why do the Defias Brotherhood have goblin technology?",a="Edwin VanCleef hired goblin engineers, craftsmen, and mercenary laborers to oversee the complex mechanical operations beneath Westfall, including steam-powered forges, gun foundries, and woodmills.",al={"defias goblins","why are goblins in deadmines"}},{q="Can the shredder be hacked or controlled by engineers?",a="Clever inventors carrying a Gnomish Universal Remote can briefly override the shredder's control systems, temporarily wresting control of the machine away from Sneed.",al={"control sneed shredder","gnomish universal remote sneed"}},{q="Does Sneed's Shredder carry anything valuable?",a="Yes. Its intact power supply, the Gnoam Sprecklesprocket, is sought by Shoni the Shilent in Stormwind, who needs it to power the gnomes' gyrodrillmatic excavationators for an assault on Gnomeregan.",al={"sneed shredder quest item","what drops from sneed shredder"}},{q="Who pilots the shredder?",a="The machine is commanded by Sneed, a seasoned goblin supervisor who directs the logging and carpentry operations deep within the Deadmines.",al={"who drives sneed shredder","sneed pilot"}}},ang={["profession:Engineering"]="The shredder is a classic marvel of goblin mechanical design, though it remains vulnerable to the overrides of a Gnomish Universal Remote.",["race:Gnome"]="Shoni the Shilent of the Gnomeregan underground assault crew wants this goblin-built monster's power supply to drive the drills that could reopen the way to Gnomeregan.",["faction:Alliance"]="Eliminating Sneed and his machine cripples the lumber milling operations supporting Edwin VanCleef's secret war fleet."},kw={"buzzsaw","deadmines","defias","goblin","lumber","remote","shredder","sneed","vancleef"},rel={"npc:sneed","zone:deadmines","subzone:deadmines","quest:2040","topic:goblin"},src={"Sneed's Shredder"}}
E["npc:wilder-thistlenettle"] = {t="npc",n="Wilder Thistlenettle",z="deadmines",s="Wilder Thistlenettle is a dwarven miner brooding in a tavern within Stormwind's Dwarven District. The sole survivor of a tragic cave-in deep within the Deadmines, he is haunted by the gruesome fate of his mining company and his brother.",h="Wilder Thistlenettle is a dwarven miner brooding in a tavern within Stormwind's Dwarven District.",sec={{t="A Bitter Survivor",b="Wilder Thistlenettle can be found drowning his sorrows in an alehouse near the southeastern gates of the Dwarven District. Years ago, he joined an expedition into the deep lodes of Moonbrook's Deadmines alongside his brother and their companions. A catastrophic cave-in sealed the rest of the crew in the dark while Wilder barely made it to the surface alive.",sp=0},{t="Ghosts of the Deep",b="The disaster in the tunnels did not end in peaceful rest. Wilder eventually learned that his brother and the lost mining company did not merely perish in the rubble—dark magic or unfinished business has animated them as restless undead, endlessly haunting the subterranean ruins. Consumed by grief and survivor's guilt, Wilder seeks brave adventurers willing to brave the Deadmines to recover mementos of the fallen and grant his brother final peace.",sp=1}},faq={{q="Where can I find Wilder Thistlenettle?",a="He sits inside a quiet pub in Stormwind City's Dwarven District, located just inside the right side of the district's southeastern entrance.",al={"wilder thistlenettle location","where is wilder","thistlenettle stormwind"}},{q="What happened to his brother in the Deadmines?",a="Wilder's brother was trapped in a sudden tunnel collapse alongside their fellow miners. Instead of remaining at rest, the dead miners arose as undead horrors condemned to wander the shadowed subterranean shafts.",al={"wilder brother deadmines","what happened to brother","thistlenettle brother lore"}},{q="Why does Wilder need adventurers?",a="Unable to face the horrors of the mines himself, Wilder asks travelers heading into the Deadmines to recover personal mining union badges from the lost workers and to put his undead brother out of his misery.",al={"wilder quests","what does wilder want","collecting memories quest"}}},ang={["race:Dwarf"]="For dwarven kin, Wilder's grief strikes a familiar cord, highlighting the ever-present perils of subterranean delvings and the sacred need to honor fallen guild brothers.",["profession:Mining"]="Miners readily understand the hazards of deep subterranean veins, where unstable earth and forgotten dark magic can entomb even seasoned crews."},kw={"brother","cave-in","deadmines","dwarven district","miner","stormwind","thistlenettle","wilder"},rel={"quest:167","quest:168","subzone:dwarven-district","zone:stormwind","zone:deadmines","subzone:deadmines","topic:dwarf","topic:stormwind-kingdom"},src={"Wilder Thistlenettle"}}
E["quest:166"] = {t="quest",n="The Defias Brotherhood",z="deadmines",s="This mission represents the culmination of Gryan Stoutmantle's long campaign to reclaim Westfall from outlaw rule. Tasked with entering the Deadmines, Alliance champions must breach the criminal hideout and strike down the mastermind Edwin VanCleef himself.",h="This mission represents the culmination of Gryan Stoutmantle's long campaign to reclaim Westfall from outlaw...",sec={{t="A Sentence Passed",b="For months, Gryan Stoutmantle and the beleaguered People's Militia have fought a desperate holding action against the Defias Brotherhood across Westfall. With the true location of the thieves' stronghold uncovered beneath Moonbrook, Stoutmantle issues his final, grim decree: Edwin VanCleef must be assassinated to break the back of the rebellion once and for all.",sp=0},{t="Into the Labyrinth",b="To carry out the execution, fighters must delve deep into the winding shafts of the Deadmines. Past renegade stonemasons, goblin engineers, and heavy iron blast doors lies the central dry dock, where VanCleef oversees the final construction of his grand war vessel. Taking his head severs the command structure holding the entire outlaw network together.",sp=1},{t="Shadows of a Greater Conspiracy",b="While Stoutmantle believes VanCleef's death marks the beginning of the end for the Brotherhood, the fallen guildmaster's corpse holds troubling secrets. Upon his body rests an unsent letter, hinting that the uprising in Westfall was never an isolated revolt, but part of a wider, darker web stretching into the very nobility of Stormwind City.",sp=2}},faq={{q="What is the goal of this quest?",a="You are tasked by Gryan Stoutmantle to venture into the Deadmines dungeon in Moonbrook, eliminate Edwin VanCleef, and return with his severed head to Sentinel Hill.",al={"quest objective","what do i do","what is this quest"}},{q="Who is Edwin VanCleef?",a="Edwin VanCleef was formerly the Grand Mason of the Stonemasons Guild who led the rebuilding of Stormwind City after the First and Second Wars. After a bitter dispute over payment with the House of Nobles, he founded the Defias Brotherhood to exact vengeance upon the kingdom.",al={"who is vancleef","vancleef identity","edwin vancleef lore"}},{q="Why does Gryan Stoutmantle order an assassination?",a="The People's Militia lacks the regular army reinforcements from Stormwind needed to fight an enduring war. Stoutmantle recognizes that decapitating the leadership is Westfall's only realistic chance of breaking the syndicate's stranglehold on the farmlands.",al={"why kill vancleef","stoutmantle motive","why death penalty"}},{q="Where can Edwin VanCleef be found?",a="He commands his followers from the bridge of the massive ironclad juggernaut moored deep inside the Deadmines, located beneath the abandoned town of Moonbrook.",al={"vancleef location","where is edwin vancleef","deadmines boss location"}},{q="Does killing VanCleef destroy the Defias completely?",a="Though Stoutmantle hopes it signals the end, scattered cells and hidden leaders persist across Westfall, the Redridge Mountains, and Duskwood. Furthermore, discoveries made upon his body point toward deeper corruption that outlives VanCleef himself.",al={"is defias defeated","are defias gone","end of brotherhood"},sp=1},{q="What item of note is found on VanCleef upon his defeat?",a="Along with his head, VanCleef carries An Unsent Letter, which begins a new investigation of its own.",al={"vancleef drop","unsent letter","what does vancleef drop"},sp=1}},ang={["race:Human"]="For humans of the kingdom, striking down VanCleef is a bittersweet tragedy, cutting down the very artisan whose hands rebuilt their capital out of ashes.",["faction:Alliance"]="This mission marks a critical early victory for the Alliance, securing the breadbasket of Westfall when the throne of Stormwind cannot spare its own troops.",["class:Rogue"]="VanCleef is a legendary rogue and master artisan; crossing blades with him in his inner sanctum tests the martial training of any stealth operative."},kw={"deadmines","head","juggernaut","militia","moonbrook","stonemasons","stoutmantle","vancleef","westfall"},rel={"npc:edwin-vancleef","npc:gryan-stoutmantle","zone:deadmines","topic:defias-brotherhood","zone:westfall","quest:12","quest:65","topic:alliance"},m={start="Gryan Stoutmantle",level="22",faction="Alliance",id=166},src={"The Defias Brotherhood (7)"}}
E["quest:167"] = {t="quest",n="Oh Brother. . .",z="deadmines",s="\"Oh Brother. . .\" is an Alliance mission given by Wilder Thistlenettle in Stormwind City. Distraught over a cave-in during an expedition into the depths beneath Moonbrook, Wilder asks adventurers to search the labyrinthine mines for his missing sibling, Foreman Thistlenettle, or recover his Explorers' League Badge.",h="\"Oh Brother.",sec={{t="A Trapped Expedition",b="Wilder Thistlenettle and his brother entered the cavernous subterranean tunnels beneath Moonbrook on an expedition for the Explorers' League. However, things turned catastrophic when hostile thieves swarmed the area and a violent cave-in sealed off the lower tunnels. Wilder managed to escape to Stormwind, but his brother and the rest of the crew were left trapped behind the rubble.",sp=0},{t="The Grim Fate of Foreman Thistlenettle",b="The truth awaiting any rescuer who pushes deep into the Deadmines tunnels is tragic. Foreman Thistlenettle did not survive the entombment; instead, dark energies stirring within the abandoned mines reanimated the unfortunate dwarf into an undead husk. Wandering the subterranean caverns alongside other restless corpses, the foreman retains only his prized Explorers' League Badge as a token of who he once was.",sp=1}},faq={{q="Where do I start the quest \"Oh Brother. . .\"?",a="The quest is offered by Wilder Thistlenettle, who can be found in the Dwarven District of Stormwind City.",al={"quest giver oh brother","who gives oh brother","where to get oh brother"}},{q="Where is Foreman Thistlenettle located?",a="Foreman Thistlenettle wanders the exterior mine corridors of the Deadmines, located beneath the town of Moonbrook in Westfall. He is in the undead-infested section of the tunnels outside the instance portal.",al={"foreman thistlenettle location","where is thistlenettle","where is the brother"}},{q="What happened to Foreman Thistlenettle?",a="A cave-in trapped Foreman Thistlenettle and his mining party inside the caverns, and none of them have been heard from since. Finding him, or at least his badge, is the only way Wilder will learn his brother's fate.",al={"is thistlenettle alive","what happened to the brother","thistlenettle lore"},sp=1},{q="What item do I need to retrieve?",a="You need to retrieve Foreman Thistlenettle's Explorers' League Badge, which he always carried; find the foreman deep in the Deadmines tunnels and the badge will be with him.",al={"oh brother quest item","what drops for oh brother"},sp=1},{q="What was the expedition doing in Moonbrook?",a="The Thistlenettle brothers were surveying the vast mine complex on behalf of the Explorers' League before being ambushed by Defias bandits and separated by a sudden tunnel collapse.",al={"why were the dwarves in westfall","explorers league deadmines","why were they in moonbrook"}},{q="Is this quest completed inside the Deadmines dungeon instance?",a="No, you do not need to zone inside the dungeon instance. Foreman Thistlenettle is an elite mob who roams the contested mine tunnels that lead up to the instance portal.",al={"is oh brother inside deadmines instance","do i need a dungeon group"}}},ang={["race:Dwarf"]="The tragic demise of an Explorers' League foreman in human lands hits home for any dwarf who values brotherhood, stonecutting, and the League's tireless work.",["faction:Alliance"]="The Deadmines are a blight on Stormwind's doorstep, and this quest shows how deeply the Defias and subterranean horrors have harmed innocent citizens."},kw={"badge","deadmines","explorers' league","moonbrook","stormwind","thistlenettle","undead","westfall","wilder"},rel={"npc:wilder-thistlenettle","zone:deadmines","subzone:deadmines","subzone:moonbrook","zone:westfall","topic:explorers-league","topic:stormwind-kingdom"},m={start="Wilder Thistlenettle",level="20",faction="Alliance",id=167},src={"Oh Brother. . ."}}
E["quest:168"] = {t="quest",n="Collecting Memories",z="deadmines",s="Collecting Memories is a solemn task entrusted by the dwarven miner Wilder Thistlenettle in Stormwind City. He asks adventurers braving the ruined mines beneath Moonbrook to recover the Miners' Union Cards of his fallen coworkers. Bringing these tokens back offers grieving families in the capital closure following a catastrophic cave-in.",h="Collecting Memories is a solemn task entrusted by the dwarven miner Wilder Thistlenettle in Stormwind City.",sec={{t="A Tragic Collapse",b="Before Moonbrook fell completely into lawlessness and the shadow of the Defias Brotherhood, the mines of Westfall were an active source of livelihood for many working-class families. Wilder Thistlenettle survived a devastating cave-in that buried a wing of the labyrinthine tunnels, but many of his friends and coworkers were not so fortunate. Cut off from rescue, those workers perished deep underground, leaving behind mourning kin in Stormwind who never received true confirmation or closure regarding their loved ones' fates.",sp=0},{t="Restless Remains",b="The tunnels outside the main subterranean iron works are no longer silent tombs. The souls of the miners who perished in the collapse now wander the dark passages as restless, undead husks. To recover the Miners' Union Cards, travelers must navigate these haunted shafts, facing the animated remains of the very diggers Wilder once worked alongside. Returning these cards to Stormwind ensures their kin finally learn the truth and gives Wilder a chance to honor his fallen brethren.",sp=0}},faq={{q="Who is Wilder Thistlenettle?",a="Wilder Thistlenettle is a dwarven miner residing in Stormwind City. Having survived a catastrophic tunnel cave-in beneath Westfall that claimed the lives of his close coworkers, he seeks to bring peace and confirmation to their surviving families.",al={"wilder thistlenettle","quest giver","who gives collecting memories"}},{q="What happened to the miners in the Deadmines?",a="A devastating tunnel collapse trapped and killed an entire crew of miners in a wing of the Moonbrook dig sites. Deprived of rescue and proper burial, their spirits and bodies have risen as restless undead haunting the abandoned passages.",al={"why are there undead miners","mine collapse","deadmines cave in"}},{q="Why does Wilder want their Miners' Union Cards?",a="The union cards serve as formal identification for the workers who died in the collapse. Because the bodies were never recovered, retrieving their cards allows Wilder to formally notify their families in Stormwind and offer them closure.",al={"what are the union cards for","miners union cards"}},{q="Where are the union cards found?",a="The cards are found in the haunted, outer tunnels beneath Moonbrook, situated in the corridors just before entering the secured threshold of the Deadmines proper.",al={"where do i find the cards","undead deadmines location","where are the dead miners"}},{q="Did the Defias Brotherhood cause the cave-in?",a="Wilder Thistlenettle simply recalls it as a horrible mining accident and tunnel cave-in. While the Defias Brotherhood now rules the deep passages of the Deadmines, the tragedy itself appears to be a disastrous industrial collapse that trapped his fellow miners.",al={"did defias cause the cave in","who collapsed the mine"}},{q="Are the miners considered part of the Defias Brotherhood?",a="No. They were ordinary union laborers working the mines when the cave-in struck. Their restless undead remnants roam the cavern peripheries separate from Edwin VanCleef's organized Defias forces further inside.",al={"are dead miners defias","are undead miners with defias"}}},ang={["profession:Mining"]="Every miner understands the lingering dread of a shaft collapse, giving this mission to recover lost union cards a profound, somber resonance for pick-wielders.",["race:Dwarf"]="Dwarves place great value on the bonds forged underground and the sanctity of fallen brethren, making Wilder Thistlenettle's plea personal to fellow stone-kin.",["faction:Alliance"]="Retrieving the tokens of fallen Westfall workers directly supports the grieving working-class families enduring hard times within the walls of Stormwind."},kw={"collecting memories","deadmines","miners union card","moonbrook","stormwind","undead miners","wilder thistlenettle"},rel={"npc:wilder-thistlenettle","zone:deadmines","subzone:deadmines","subzone:moonbrook","topic:stormwind-kingdom"},m={start="Wilder Thistlenettle",level="18",faction="Alliance",id=168},src={"Collecting Memories"}}
E["quest:2040"] = {t="quest",n="Underground Assault",z="deadmines",s="Underground Assault is an Alliance quest offered by Shoni the Shilent in Stormwind City's Dwarven District. Tasked with aiding the displaced gnomes, adventurers venture into the Deadmines to salvage an intact power core from a goblin shredder. This stolen component is destined to power drilling machines intended to spearhead the liberation of Gnomeregan.",h="Underground Assault is an Alliance quest offered by Shoni the Shilent in Stormwind City's Dwarven District.",sec={{t="A Desperate Ingenuity",b="Following the catastrophic fall of Gnomeregan to the primitive troggs, surviving gnomish tinkerers have been forced into exile across Khaz Modan and Stormwind. Rather than wallowing in defeat, engineers like Shoni the Shilent are already devising mechanical operations to breach their lost home. The primary obstacle is the dense, subterranean rock surrounding the technocratic city, requiring massive tunneling engines known as gyrodrillmatic excavationators. Lacking the necessary localized power grids in human lands, the gnomes have turned their sights to an unlikely and volatile alternative: goblin heavy machinery operating in the criminal underworld.",sp=0},{t="Looting the Defias Foundries",b="Deep within the twisting shafts of the Deadmines in Westfall, Edwin VanCleef's Defias Brotherhood employs goblin engineers to manufacture war machines, including a fully operational goblin shredder. Shoni directs Alliance operatives to infiltrate this foundry, destroy or dismantle the lumbering automaton, and recover its specialized heart—the Gnoam Sprecklesprocket. By commandeering the potent goblin power supply, the exiled gnomes gain the raw mechanical output needed to bore through the subterranean perimeter and launch a counteroffensive to reclaim Gnomeregan.",sp=0}},faq={{q="Who gives the Underground Assault quest?",a="The quest is given by Shoni the Shilent, a gnomish engineer located in the Dwarven District of Stormwind City. Adventurers are often directed to her after speaking with other gnomes who mention her ambitious plans.",al={"quest giver underground assault","who gives underground assault","shoni quest"}},{q="Where do I find the Gnoam Sprecklesprocket?",a="The Gnoam Sprecklesprocket is recovered from a functional goblin shredder deep within the foundry tunnels of the Deadmines in Westfall.",al={"sprecklesprocket location","where is sprecklesprocket","shredder part deadmines"}},{q="Why does Shoni need parts from a goblin shredder?",a="Gnomish gyrodrillmatic excavationators need an immense, portable power supply to breach the reinforced subterranean borders around Gnomeregan. The heavy-duty power core running the Defias Brotherhood's goblin shredder provides the exact mechanical output required for the drills.",al={"why goblin parts","why shredder power supply","sprecklesprocket purpose"}},{q="What is the broader goal of this mission?",a="The mission supports the future liberation of Gnomeregan. By powering up heavy excavation drills, the exiled gnomes intend to tunnel directly through the rocky perimeter of their captured city and mount a surprise assault against the occupying troggs.",al={"why do underground assault","reclaiming gnomeregan quest","gnome assault plan"}},{q="What happened to Gnomeregan that caused this assault to be planned?",a="Gnomeregan was overwhelmed by a subterranean trogg invasion emerging from deep beneath the city. In the chaotic defense, the city was contaminated by toxic radiation, forcing the surviving gnomish populace to flee to Ironforge and Stormwind as refugees.",al={"why did gnomeregan fall","what happened to gnomeregan","trogg invasion"}},{q="Are the Defias Brotherhood and the troggs allied?",a="No, they have no connection. The Defias Brotherhood merely hired goblin tinkerers to build warmachines in Westfall. Shoni simply exploits the Defias presence in the Deadmines as a convenient source of high-yield goblin technology.",al={"defias and troggs","are troggs with defias"}}},ang={["race:Gnome"]="For exiled gnomish adventurers, salvaging this power core is a personal step toward piercing the rocky walls of their fallen home and driving the troggs out of Gnomeregan.",["profession:Engineering"]="Tinkers will appreciate the audacious engineering behind cannibalizing a brutal goblin shredder power core to fuel precision gnomish excavation machinery.",["faction:Alliance"]="Assisting the displaced gnomes of the Dwarven District strengthens the bond between Stormwind and its exiled allies while striking a blow against the Defias supply line."},kw={"deadmines","gnoam sprecklesprocket","gnomeregan","goblin shredder","gyrodrillmatic","shoni the shilent","troggs","underground assault"},rel={"npc:shoni-the-shilent","quest:2041","zone:deadmines","zone:gnomeregan","topic:gnome","topic:goblin","topic:trogg","quest:2928"},m={start="Shoni the Shilent",level="20",faction="Alliance",id=2040},src={"Underground Assault"}}
E["quest:214"] = {t="quest",n="Red Silk Bandanas",z="deadmines",s="Red Silk Bandanas is a mission issued by Scout Riell on behalf of the People's Militia. It directs Alliance adventurers into the Deadmines to hunt down high-ranking Defias operatives and bring back their distinctive red silk masks as proof.",h="Red Silk Bandanas is a mission issued by Scout Riell on behalf of the People's Militia.",sec={{t="A Hierarchy in Cloth",b="While common cutpurses and highwaymen throughout Westfall tie coarse red cloth around their faces, the Defias Brotherhood maintains a strict internal hierarchy indicated by fabric. Scout Riell and the People's Militia have discovered that rank-and-file bandits wear rough weave, while senior conspirators and inner-circle operatives are distinguished by fine red silk. Stripping these bandanas directly targets the experienced officers coordinating Edwin VanCleef's uprising.",sp=0},{t="Striking the Core",b="Because silk marks seniority, the greatest concentration of these high-ranking outlaws gathers deep within the Deadmines beneath Moonbrook. Sentinels and scouts stationed outside Sentinel Hill rely on freelance champions to push into the contested subterranean tunnels. Every silk bandana recovered represents one less lieutenant organizing ambushes, defending weapon caches, or enforcing VanCleef's rule across Westfall.",sp=0}},faq={{q="Why do the Defias wear red bandanas?",a="The red bandana serves as the unified emblem and calling card of the Defias Brotherhood across Stormwind's territories. It conceals their identities while signaling allegiance to Edwin VanCleef's rebellious movement.",al={"defias mask meaning","why red masks","defias uniform"}},{q="What makes the red silk bandanas special compared to regular bandanas?",a="According to Scout Riell, the fabric denotes status within the Brotherhood. Common street thugs wear coarse, cheap material, while veterans, officers, and trusted lieutenants are awarded red silk.",al={"why red silk","silk vs cloth defias","silk bandana difference"}},{q="Who is Scout Riell?",a="Scout Riell is an operative serving the People's Militia in Westfall, tasked with tracking Defias movements and directing adventurers to strike at their strongholds around the Deadmines.",al={"scout riell westfall","who gives red silk bandanas quest"}},{q="Where are the Defias wearing silk bandanas located?",a="They are concentrated in and around the Deadmines beneath the town of Moonbrook, where Edwin VanCleef's senior forces oversee underground operations.",al={"where to find silk bandanas","deadmines silk bandana location"}},{q="What is the People's Militia?",a="The People's Militia is a volunteer defense force formed by Gryan Stoutmantle and the embattled farmers of Westfall to protect their lands after the Stormwind army failed to provide adequate garrisons.",al={"who are the people's militia","peoples militia westfall"}},{q="Do these bandanas have any use outside of proving a kill?",a="For the People's Militia, they serve purely as indisputable proof that high-ranking outlaws have been eliminated, weakening the command structure of the Brotherhood.",al={"can you wear red silk bandana","what are the bandanas for"}}},ang={["faction:Alliance"]="Every officer felled in the Deadmines loosens the Brotherhood's stranglehold on the breadbasket of the Kingdom of Stormwind.",["class:Rogue"]="The Defias's red silk masks represent a notorious tradition of underworld tradecraft, marking veteran cutthroats and covert conspirators.",["profession:Tailoring"]="Fine red silk is an expensive luxury for common bandits, underscoring how lavishly equipped and funded the Brotherhood's leadership truly is."},kw={"deadmines","defias brotherhood","moonbrook","peoples militia","red silk bandanas","scout riell","vancleef","westfall"},rel={"npc:scout-riell","zone:deadmines","quest:12","subzone:deadmines"},m={start="Scout Riell",level="17",faction="Alliance",id=214},src={"Red Silk Bandanas"}}
E["subzone:goblin-foundry"] = {t="subzone",n="Goblin Foundry",z="deadmines",s="The Goblin Foundry is an industrial workshop deep within the Deadmines where goblin tinkerers labored to manufacture heavy machinery for Edwin VanCleef's rebellion. Centered around a massive smelting cauldron, the chamber fell into chaos when the experimental harvest golems housed within abruptly came to life.",h="The Goblin Foundry is an industrial workshop deep within the Deadmines where goblin tinkerers labored to...",sec={{t="Industrial Ambitions",b="Carved into the subterranean depths of Moonbrook, the Goblin Foundry provided the Defias Brotherhood with the heavy manufacturing power required to fuel their uprising. Utilizing vast smelters, iron ramps, and goblin engineering expertise, the workshop mass-produced mechanical armaments. Among their most ambitious endeavors was the construction of the Foe Reaper 5000, an upgraded iteration of Westfall's familiar automated reapers.",sp=0},{t="A Malfunction in Iron",b="Goblin ingenuity notoriously borders on catastrophe, and the foundry's crowning achievement proved to be its undoing. The prototype harvest golems turned against their creators, animating uncontrollably and driving out or slaughtering the foundry's workforce. The machinery now stomps unchecked across the iron catwalks, leaving the smelters abandoned to rogue automatons.",sp=0}},faq={{q="What was being built in the Goblin Foundry?",a="The Defias Brotherhood hired goblin engineers to smelt iron and build mechanical weaponry. Their primary project was constructing powerful mechanized harvest golems, specifically the lethal prototype known as the Foe Reaper 5000.",al={"what are they making here","foundry purpose","deadmines factory"}},{q="Why are there harvest golems in the foundry?",a="The harvest golems were being manufactured and upgraded on-site by goblin artificers. However, the machines unexpectedly activated, revolted against their handlers, and took over the lower and upper tiers of the foundry floor.",al={"why harvest golems here","foundry robots","mechanical enemies deadmines"}},{q="Where are the goblins who ran this workshop?",a="Most of the foundry goblins were driven out, scattered into deeper chambers of the mine, or slain when their experimental mechanical creations went haywire and seized control of the workshop.",al={"where are the goblins","what happened to the engineers","dead goblins"}},{q="What is the large structure in the center of the room?",a="The center of the room is dominated by a massive industrial smelting cauldron used to melt down ore hauled from the mines to forge armor plates and mechanical chassis.",al={"foundry center pot","smelting vat","cauldron in deadmines"}}},ang={["profession:Engineering"]="The foundry stands as a testament to both the brilliance and hazards of goblin tinkering, showcasing how dangerous automated chassis can be when programmed without strict safety failsafes.",["faction:Alliance"]="Discovering that the rogue harvest golems terrorizing Westfall's farms were being actively upgraded into military weapons here reveals the true extent of the Defias threat."},kw={"cauldron","deadmines","defias","foe reaper 5000","goblin foundry","harvest golem","vancleef"},rel={"zone:deadmines","subzone:deadmines","subzone:cauldron","topic:goblin"},src={"Goblin Foundry"}}
E["subzone:ironclad-cove"] = {t="subzone",n="Ironclad Cove",z="deadmines",s="Ironclad Cove is a massive subterranean cavern hidden beneath Westfall, housing an underground shipyard and dock. It serves as the secret construction dock for the Defias Brotherhood's war juggernaught and connects directly to the sea.",h="Ironclad Cove is a massive subterranean cavern hidden beneath Westfall, housing an underground shipyard and...",sec={{t="The Hidden Shipyard",b="Buried at the deepest point of the Deadmines, Ironclad Cove is a monumental sea cavern converted into a fortified dockyard. Here, Edwin VanCleef and the Defias Brotherhood have constructed an enormous warship known as the juggernaught. The cavern features extensive wooden scaffolding, islets, and loading catwalks manned by Defias pirates, deckhands, and overseers. Its existence reveals the true scale of the Defias threat: VanCleef intends not merely to raid Westfall's farmsteads, but to assemble a private naval force capable of bombarding the shores of Stormwind itself.",sp=0},{t="Gateway to the Ocean",b="The cavern is dominated by colossal iron-reinforced sea doors set into the rock wall. Once opened, these gates provide a direct outlet into the Great Sea, emerging along the coastline just north of Stranglethorn Vale. Before the Defias Brotherhood seized the cove, it was held by an independent pirate crew whom the Brotherhood slaughtered to ensure total secrecy. Shielded from the eyes of the Stormwind naval fleet, the cove provides the Brotherhood an unmonitored lane for moving contraband, staging maritime raids, and preparing their naval assault.",sp=1}},faq={{q="What is the ship in Ironclad Cove being built for?",a="The juggernaught is the centerpiece of Edwin VanCleef's military ambitions. The Defias Brotherhood assembled this massive warship deep beneath the earth so it could launch undetected through subterranean water channels and strike at Stormwind from the sea.",al={"why is there a ship here","what is the juggernaught","deadmines ship purpose"}},{q="Where does the large metal door in the cove lead?",a="The massive gates open directly into the ocean along the southern coast of Westfall, near the border of northern Stranglethorn Vale. When opened, the juggernaught can sail straight out into the Great Sea.",al={"where do the sea gates open","deadmines iron doors","exit into the ocean"}},{q="Who controls Ironclad Cove?",a="The Defias Brotherhood holds the cove under the command of Edwin VanCleef. While independent pirates originally used the secluded cavern, VanCleef's forces wiped them out to commandeer the docks and keep the juggernaught's construction entirely secret.",al={"who runs the cove","who lives in ironclad cove"}},{q="Who is the murloc aboard the ship?",a="That is Cookie, the Defias ship's cook. Armed with a rolling pin and cooking cauldrons, he is an unusual ally among the human and goblin renegades, having claimed the galley as his personal domain.",al={"cookie the murloc","why is there a murloc pirate","chef cookie"}}},ang={["faction:Alliance"]="Finding a full-sized war galleon buried under Westfall transforms the Defias from a regional bandit gang into an existential military threat against the Kingdom of Stormwind.",["class:Rogue"]="The cove represents the zenith of Edwin VanCleef's craftsmanship, engineering prowess, and underground logistics, making it legendary among thieves and outlaws."},kw={"cookie","deadmines ship","defias cove","edwin vancleef","ironclad cove","juggernaught","shipyard"},rel={"zone:deadmines","subzone:deadmines","npc:cookie","topic:pirate","zone:stranglethorn"},src={"Ironclad Cove"}}
E["subzone:mast-room"] = {t="subzone",n="Mast Room",z="deadmines",s="The Mast Room is a cavernous subterranean lumber mill nestled deep within the Deadmines. Overseen by the goblin taskmaster Sneed and his woodcarvers, this chamber processes timber stripped from Westfall.",h="The Mast Room is a cavernous subterranean lumber mill nestled deep within the Deadmines.",sec={{t="The Underground Sawmill",b="Past the deeper mine tunnels of the Deadmines lies the Mast Room, a massive cavern converted into a fully functional lumber mill. Piles of felled timber, sawdust, and massive cutting equipment dominate the space. It is here that goblin woodcarvers shape the immense masts, ribs, and planks needed to assemble the massive warship hidden further within the Ironclad Cove. Under the watchful eye of Sneed, the Defias Brotherhood transforms Westfall's harvested wood into instruments of war.",sp=1},{t="Industrial Labor",b="The chamber is an example of goblin industry at its most relentless. Sneed oversees operations from atop a mechanical shredder, ensuring the woodcarvers maintain grueling quotas. Massive logs are hoisted and planed in constant succession, turning what was once a dormant gold mine into a roaring, soot-choked naval shipyard.",sp=1}},faq={{q="Why is there a lumber mill inside an underground mine?",a="The Defias Brotherhood is secretly building a massive warship inside the cove beneath the mines. The Mast Room serves as the assembly and shaping ground for the ship's masts, framing, and hull planks, using timber smuggled from the surface of Westfall.",al={"why timber here","why wood in deadmines","mast room purpose"},sp=1},{q="Who runs the Mast Room?",a="The chamber is overseen by Sneed, a goblin master craftsman who directs the goblin woodcarvers while piloting a lethal mechanical lumber shredder.",al={"mast room boss","who leads mast room","who is sneed"}},{q="Why are goblins working here for the Defias?",a="Edwin VanCleef hired goblin engineers and craftsmen to provide technical expertise that human stonemasons lacked. The goblins provide heavy machinery, explosives, and shipwright skills in exchange for gold and profit.",al={"why are goblins in deadmines","defias goblins"},sp=1}},ang={["profession:Engineering"]="The goblin shredder operated by Sneed in this chamber is a marvel of crude steam-and-cog technology, repurposed from forest logging to crush intruders.",["faction:Alliance"]="The timber processed in this chamber reveals that Defias pillaging across Westfall serves a coordinated industrial effort rather than simple banditry."},kw={"deadmines","goblin woodcarver","lumber mill","mast room","shredder","sneed"},rel={"npc:sneed","zone:deadmines","topic:goblin"},src={"Mast Room"}}
E["zone:deadmines"] = {t="dungeon",n="The Deadmines",z="deadmines",s="Deep beneath the dusty farm town of Moonbrook lies the Deadmines, an enormous subterranean complex that once supplied a third of Stormwind's gold reserves. Abandoned during the First War and long considered haunted, these labyrinthine tunnels have secretly been overtaken by the Defias Brotherhood as their ultimate staging ground. Here, Edwin VanCleef and his conscripted goblin engineers labor away from the eyes of the realm to build an engine of vengeance against the kingdom.",h="Deep beneath the dusty farm town of Moonbrook lies the Deadmines, an enormous subterranean complex that once...",sec={{t="A Legacy of Gold and Ruin",b="Before the First War, the Deadmines were celebrated as the greatest gold-producing center in human lands, financing the prosperity of Stormwind. When the Orcish Horde swept through the kingdom and razed the capital, the mines were hastily abandoned to the dark. During those turbulent years, legendary figures walked these depths: Sir Anduin Lothar was imprisoned by subterranean ogres for twenty months while recovering the sacred Tome of Divinity, and Warchief Blackhand's rebellious daughter Griselda fled into the lower passages alongside the ogre Turok before both met their ends. Believed to be cursed and populated only by shambling undead and lurking subterranean vermin, the depths lay untouched for decades.",sp=0},{t="Sanctum of the Brotherhood",b="When the Stonemasons' Guild was cast out of Stormwind without payment for rebuilding the city, Edwin VanCleef reorganized the disenfranchised artisans into the Defias Brotherhood. Seeking a secure headquarters safe from Gryan Stoutmantle's People's Militia, the thieves established their central redoubt within the abandoned tunnels. They drove out the legitimate Miners' League—leaving Foreman Thistlenettle's doomed workers to perish and rise as undead ghouls—and converted the shafts into an industrial war camp. Guarded by lumbering ogres, seasoned brigands, and mechanical constructs, the lower mines echo once again with picks, fires, and illicit industry.",sp=0},{t="The Secret of Ironclad Cove",b="Beyond the sweltering Goblin Foundry and the timber-strewn Mast Room lies Ironclad Cove, a vast subterranean grotto hollowed out beneath the Dagger Hills. In this hidden harbor, VanCleef has employed goblin shipbuilders and tinkerers to construct a colossal ironclad dreadnaught. Commanded by Captain Greenskin and First Mate Mr. Smite, this warship is engineered to sail through an underwater sea gate leading out toward the ocean, providing the Defias Brotherhood with the naval firepower required to bombard and shatter Stormwind Harbor.",sp=1}},faq={{q="Where is the entrance to the Deadmines located?",a="The entrance is hidden inside a derelict barn in the ruined town of Moonbrook, located in southwestern Westfall. Winding tunnels pass through an outer complex of Defias diggers and undead miners before reaching the locked instance threshold.",al={"deadmines entrance","how to get to deadmines","where is deadmines"}},{q="Why does everyone call the Deadmines 'VC'?",a="Adventurers frequently refer to the dungeon as 'VC' after its master, Edwin VanCleef. This shorthand is used to avoid confusing the Deadmines with Dire Maul, an ancient elven complex in Feralas that shares the initials 'DM'.",al={"why vc","vc meaning","why call it vc"}},{q="Who is Edwin VanCleef?",a="Edwin VanCleef was the brilliant guildmaster of the Stonemasons who oversaw the majestic reconstruction of Stormwind City after the First War. When the House of Nobles refused to honor their debts, VanCleef formed the Defias Brotherhood to exact restitution through rebellion and open brigandage.",al={"vancleef backstory","who is the final boss","defias leader"}},{q="What is being built in Ironclad Cove?",a="The Defias have contracted goblin engineers to assemble a massive ironclad juggernaught. Armed with heavy ordnance and sturdy timber, the warship is designed to sail out of the cove's sea gate and launch an assault against the capital.",al={"what are they building","deadmines ship","juggernaught"}},{q="What happened to the Miners' League workers outside the instance?",a="Foreman Thistlenettle and his crew were sent to legally reopen the mines for the kingdom. When the Defias stormed the works, a devastating tunnel collapse trapped the miners in the dark, where they starved and eventually rose as mindless, restless undead.",al={"thistlenettle fate","why are there undead miners","collecting memories lore"}},{q="What does defeating Cookie the murloc mean for the Defias ship?",a="Cookie serves as the bizarre ship's cook aboard VanCleef's dreadnaught. While defeating VanCleef cuts off the head of the rebellion, slaying Cookie cleans out the remaining crew lingering in the ship's galley, utterly breaking the crew's presence in Ironclad Cove before adventurers escape out the coastal passage.",al={"cookie the murloc","why is cookie a boss","cookie deadmines"}},{q="Where does the exit tunnel lead when leaving the dungeon?",a="Following the natural tunnel out behind the dreadnaught brings adventurers to an exit along the coastal bluffs of the Dagger Hills, looking out toward the ocean and the Westfall Lighthouse.",al={"deadmines exit","where does the exit go"}}},ang={["faction:Alliance"]="The Deadmines represent the gravest internal threat to the kingdom of Stormwind; bringing down VanCleef is the defining victory that restores hope to the besieged farmers of Westfall.",["class:Paladin"]="These desecrated shafts are a test of valor and faith, echoing the historic trials of Sir Anduin Lothar and the lost miners whose restless dead still wander the outer tunnels.",["profession:Mining"]="Once supplying a third of the capital's wealth, the rocky tunnels remain rich in veins of copper, tin, and precious silver.",["profession:Engineering"]="The Goblin Foundry and Sneed's mechanical workshop offer an inside look at cutting-edge steam shredders, remote-controlled golems, and specialized ordnance."},kw={"cookie","deadmines","defias","edwin vancleef","ironclad cove","juggernaught","moonbrook","mr. smite","vancleef","westfall"},rel={"topic:defias-brotherhood","npc:edwin-vancleef","zone:westfall","subzone:moonbrook","subzone:ironclad-cove","npc:mr-smite","quest:65","quest:373"},m={levels="17-26"},src={"Deadmines (Classic)","Deadmines"}}
